                this.currentSlide = 0;
                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupScrollNav();

                // Initialize progress bar
                this.progressBar = document.getElementById('progressBar');
                this.updateProgressBar();

                // Force first slide visible immediately
                if(this.slides.length > 0) {
                    this.slides[0].classList.add('visible');
                }
            }

            setupIntersectionObserver() {
                const options = { root: null, rootMargin: '0px', threshold: 0.3 };
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            // Update current slide index based on what's visible
                            this.currentSlide = Array.from(this.slides).indexOf(entry.target);
                            this.updateProgressBar();
                        }
                    });
                }, options);

                this.slides.forEach(slide => observer.observe(slide));
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowDown' || e.key === 'ArrowRight' || e.key === 'PageDown' || e.key === ' ') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide + 1);
                    } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft' || e.key === 'PageUp') {
                        e.preventDefault();
                        this.goToSlide(this.currentSlide - 1);
                    }
                });
            }

            setupScrollNav() {
                // Prevent aggressive trackpad scrolling from skipping slides
                let isScrolling = false;
                document.addEventListener('wheel', (e) => {
                    if (isScrolling) return;
                    if (Math.abs(e.deltaY) > 50) {
                        isScrolling = true;
                        if (e.deltaY > 0) this.goToSlide(this.currentSlide + 1);
                        else this.goToSlide(this.currentSlide - 1);
                        setTimeout(() => { isScrolling = false; }, 800);
                    }
                }, { passive: true });
            }

            goToSlide(index) {
                if (index >= 0 && index < this.slides.length) {
                    this.slides[index].scrollIntoView({ behavior: 'smooth' });
                }
            }

            updateProgressBar() {
                if(this.progressBar && this.slides.length > 1) {
                    const percentage = (this.currentSlide / (this.slides.length - 1)) * 100;
                    this.progressBar.style.width = percentage + '%';
                }
            }
        }

